// -------------------------------------------------------------------------------------------
// the declaration

/// [definition] **A refinement as declared** (module header): the receiving ring `R`, the words
/// `K`, each word's full ticks `w`, the stations `m` and the termination class, with the receiver's
/// grain `L_R` read from the ring's declared receiver.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Refinement {
    ring: usize,
    words: usize,
    span: usize,
    stations: usize,
    termination: usize,
    grain: u64,
    period: u64,
}

impl Refinement {
    /// **Declare a refinement** on a field: refused unless the ring has a declared receiver (its
    /// receiving map `R` and grain), `K, w, m ≥ 1`, the stations lie within one turn of the
    /// receiving ring (`m ≤ d_R`) and the termination class is a class of the exterior chart.
    pub fn declare(
        field: &Field,
        ring: usize,
        words: usize,
        span: usize,
        stations: usize,
        termination: usize,
    ) -> Result<Self, HnnError> {
        let receiver = field
            .receivers()
            .iter()
            .find(|receiver| receiver.ring == ring)
            .ok_or(HnnError::MissingReceivingMap { ring })?;
        if words == 0 || span == 0 || stations == 0 {
            return Err(HnnError::NonpositiveDeclaration);
        }
        let period = field.ring(ring).period();
        if stations as u64 > period {
            return Err(HnnError::Shape {
                what: "the section's stations within one turn of the receiving ring",
                expected: period as usize,
                found: stations,
            });
        }
        if termination >= field.alphabet() {
            return Err(HnnError::CellOutside {
                code: termination,
                alphabet: field.alphabet(),
            });
        }
        if !receiver.tolerance.is_positive() {
            return Err(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            });
        }
        let grain = receiver
            .tolerance
            .recip()
            .ceil()
            .to_integer()
            .to_u64()
            .ok_or(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            })?;
        Ok(Self {
            ring,
            words,
            span,
            stations,
            termination,
            grain,
            period,
        })
    }

    /// `R`.
    pub fn ring(&self) -> usize {
        self.ring
    }

    /// `K`.
    pub fn words(&self) -> usize {
        self.words
    }

    /// `w`.
    pub fn span(&self) -> usize {
        self.span
    }

    /// `m`.
    pub fn stations(&self) -> usize {
        self.stations
    }

    /// The termination class.
    pub fn termination(&self) -> usize {
        self.termination
    }

    /// `L_R`.
    pub fn grain(&self) -> u64 {
        self.grain
    }

    /// **The junction step the section is read at**, `K·w` on the refinement's clock (the last
    /// word's last junction).
    pub fn last_epoch(&self) -> usize {
        self.words * self.span
    }

    /// **The refinement's reach** (the certified step's reading; `hnn::constitution::Reach`): its
    /// `m` stations read the receiving ring's anchor after `K·w` full ticks, and the request's moment
    /// enters at the open of every word, `n·w` for `n < K`; `phases` the most phases one moment
    /// occupied.
    pub fn reach(&self, phases: u64) -> Reach {
        Reach {
            receiver: self.ring,
            stations: vec![self.last_epoch() as u64; self.stations],
            entries: (0..self.words).map(|n| (n * self.span) as u64).collect(),
            phases,
        }
    }

    /// **The refinement's causal diamond** (Lean `HNN/Retention.diamond_recursion`): the field's
    /// source rings reach, the receiving ring observes, over `K·w` rounds.
    pub fn diamond(&self, field: &Field) -> Diamond {
        Diamond::over(field, self.ring, self.last_epoch())
    }

    /// **Station `j`'s phase on the response clock**, `(1 + j)/d_R` turns: the tick `τ + 1 + j` of
    /// the receiving ring's clock unwound from the request's last tick, read in the section's frame
    /// (module header). Its whole part is the station's winding.
    pub fn station_turns(&self, station: usize) -> Rat {
        Rat::new(
            BigInt::from(station as u64 + 1),
            BigInt::from(self.period),
        )
    }

    /// **The section's placement** (module header, "Order is carried by residues and relative
    /// phases"): the locked data `cells[j]` (an unlocked station `None`) placed on the receiving
    /// ring's spectrum at their stations' residues ([`SourceMoment::section`]).
    pub fn section(
        &self,
        field: &Field,
        current: &Current,
        cells: &[Option<usize>],
    ) -> Result<SourceMoment, HnnError> {
        if cells.len() != self.stations {
            return Err(HnnError::Shape {
                what: "one cell slot per station",
                expected: self.stations,
                found: cells.len(),
            });
        }
        SourceMoment::section(field, current, self.ring, cells)
    }

    /// **The target phases of the section** (`hnn::ratio::TargetPhases`): each station's phase on
    /// the response clock, the section's frame carrying no stream winding (branch zero).
    pub fn target_phases(&self) -> TargetPhases {
        TargetPhases {
            branch: BigInt::zero(),
            phases: (0..self.stations).map(|j| self.station_turns(j)).collect(),
        }
    }
}

// -------------------------------------------------------------------------------------------
// the balance

/// [definition] **The refinement's balance** (module header, the first check): the field's power
/// plus the resonators' energy at the first word's open (`open`) and at the last junction (`end`),
/// every tick's stated terms summed over the `K` words, the jump at each later word's open
/// (`injected`, the request's moment re-entering, the only jump), the executed residual (every
/// tick's field residual with its loaded split, the resonators' chart and split, and the last
/// junction's) with its certified bound, whether every tick's own balance closes, whether the ticks
/// chain (each tick opens at the power and resonator energy the one before left, and a word's open
/// changes no resonator energy), and the commit when one follows.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RefinementBalance {
    pub words: usize,
    pub ticks: usize,
    pub open: Rat,
    pub end: Rat,
    pub injected: Rat,
    pub dissipation: Rat,
    pub resist: Rat,
    pub contrast: Rat,
    pub pump: Rat,
    pub resonator_dissipation: Rat,
    pub interconnection: Rat,
    pub residual: Rat,
    pub bound: Rat,
    pub every_tick_closes: bool,
    pub chained: bool,
    pub commit: Option<CommitWork>,
    /// The end change's power and resonator energy under the cut's forms, read at the commit: the
    /// commit's identity reads it against `end`.
    pub committed_from: Option<Rat>,
}

impl RefinementBalance {
    /// **The balance of a refinement's words**, the last ended at its last junction.
    fn of(words: &[Word<'_>]) -> Result<Self, HnnError> {
        let mut balance = Self {
            words: words.len(),
            ticks: 0,
            open: Rat::zero(),
            end: Rat::zero(),
            injected: Rat::zero(),
            dissipation: Rat::zero(),
            resist: Rat::zero(),
            contrast: Rat::zero(),
            pump: Rat::zero(),
            resonator_dissipation: Rat::zero(),
            interconnection: Rat::zero(),
            residual: Rat::zero(),
            bound: Rat::zero(),
            every_tick_closes: true,
            chained: true,
            commit: None,
            committed_from: None,
        };
        let mut previous: Option<(Rat, Rat)> = None;
        for (n, word) in words.iter().enumerate() {
            let fields = word.field_balances();
            let (first, last) = match (fields.first(), fields.last()) {
                (Some(first), Some(last)) => (first, last),
                _ => {
                    return Err(HnnError::Shape {
                        what: "a refinement word with at least one full tick",
                        expected: 1,
                        found: 0,
                    });
                }
            };
            match &previous {
                None => balance.open = &first.before + &first.resonator_before,
                Some((power, resonance)) => {
                    balance.injected += &first.before - power;
                    balance.chained &= first.resonator_before == *resonance;
                }
            }
            for (t, tick) in fields.iter().enumerate() {
                balance.ticks += 1;
                balance.every_tick_closes &= tick.closes();
                if let Some(next) = fields.get(t + 1) {
                    balance.chained &= tick.after == next.before
                        && tick.resonator_after == next.resonator_before;
                }
                balance.dissipation += &tick.dissipation;
                balance.resist += &tick.resist;
                balance.contrast += &tick.contrast;
                balance.pump += &tick.pump;
                balance.resonator_dissipation += &tick.resonator_dissipation;
                balance.interconnection += &tick.interconnection;
                balance.residual +=
                    tick.residual() + &tick.resonator_chart + &tick.resonator_split;
                balance.bound += &tick.bound + &tick.resonator_bound;
            }
            previous = Some((last.after.clone(), last.resonator_after.clone()));
            if n + 1 == words.len() {
                let released = word.released()?;
                balance.residual += &released.last;
                balance.bound += &released.last_bound;
                balance.end = &released.power + &last.resonator_after;
            }
        }
        Ok(balance)
    }

    /// The stated terms' sum: what the refinement's identity adds to its open.
    fn terms(&self) -> Rat {
        -&self.dissipation + &self.resist + &self.contrast + &self.residual + &self.pump
            - &self.resonator_dissipation
            + &self.interconnection
            + &self.injected
    }

    /// **It closes**: `end = open − dissipation + resist + Π_c + residual + pump − resonator
    /// dissipation + interconnection + injected`, the executed residual within its bound, every tick
    /// closing, the ticks chaining; and, when a commit follows, the end change's power under the
    /// committed forms is the end plus the deposition work `½⟨x, ΔΘ x⟩` (Lean
    /// `HNN/Word.field_commit_deposition`).
    pub fn closes(&self) -> bool {
        let identity = self.end == &self.open + self.terms();
        let committed = match (&self.commit, &self.committed_from) {
            (Some(commit), Some(from)) => {
                *from == self.end && commit.committed == &self.end + &commit.deposition
            }
            (None, None) => true,
            _ => false,
        };
        identity
            && self.residual.abs() <= self.bound
            && self.every_tick_closes
            && self.chained
            && committed
    }

    /// **The committed energy bound of the refinement** (`hnn::constitution`'s header, "The
    /// committed energy bound, enforced at the commit"; Lean `Holon/Deposition.{committed_energy_bound,
    /// active_element_growth}`), read after its commit: with the per-tick amplitude growth `g = 1 + ω`
    /// of the constitution it ran at and the commit's certified storage growth `ε_k`, the committed
    /// energy is at most
    ///
    /// ```text
    /// (1 + ε_k) · (Σ_(n<K) g^(K·w − n·w) · √P_inj + g^(K·w) · √((K·w + 1) · r))²
    /// ```
    ///
    /// `P_inj` the injection's power (the balance's open: the change opens at rest), each word
    /// re-injecting it; `r` the executed residual's certified bound. Each passive tick keeps the
    /// power and a contrast port's tick multiplies it by at most `g²` (`active_element_growth`), so
    /// `√P(t+1) ≤ g√P(t) + √|r_t|`, an injection adds `√P_inj` to `√P` (the triangle inequality in
    /// the power's norm), and `Σ_t √|r_t| ≤ √((K·w + 1) Σ_t |r_t|)`; the commit's deposition work
    /// is at most `ε_k` times the storage part (`certify_deposit`). The square roots are read at
    /// their dyadic ceilings on the word's transient lattice. Refused before a commit.
    pub fn energy_bound(
        &self,
        declared: &Refinement,
        amplitude: &Rat,
        storage_growth: &Rat,
        lattice: Option<&WordLattice>,
    ) -> Result<EnergyBound, HnnError> {
        let commit = self.commit.as_ref().ok_or(HnnError::Shape {
            what: "a refinement's balance carried across its commit",
            expected: 1,
            found: 0,
        })?;
        let grain = lattice.map_or(0, WordLattice::transient_exponent);
        let ticks = declared.last_epoch() as u64;
        let entries: Rat = (0..declared.words)
            .map(|n| power(amplitude, ticks - (n * declared.span) as u64))
            .sum();
        let residual = sqrt_ceiling(
            &(Rat::from_integer(BigInt::from(ticks + 1)) * self.bound.abs()),
            grain,
        );
        let root = entries * sqrt_ceiling(&self.open, grain) + power(amplitude, ticks) * residual;
        let bound = (Rat::one() + storage_growth) * &root * &root;
        Ok(EnergyBound {
            holds: commit.committed <= bound,
            committed: commit.committed.clone(),
            bound,
        })
    }

    /// **Carry the balance across the commit** from the cut's form `before` to the committed form
    /// `after` (both read at the refinement's lift): the deposition work on the end change and the
    /// end change's power and resonator energy under the committed forms.
    pub fn commit(
        &mut self,
        before: &PowerForm,
        after: &PowerForm,
        change: &EndChange,
    ) -> Result<(), HnnError> {
        let deposition = before.deposition_work(after, change)?;
        let from = before.power(change)? + before.resonator_power(change)?;
        let committed = after.power(change)? + after.resonator_power(change)?;
        self.committed_from = Some(from);
        self.commit = Some(CommitWork {
            deposition,
            committed,
        });
        Ok(())
    }
}

/// [definition] **A refinement's committed energy against its bound**
/// ([`RefinementBalance::energy_bound`]): the committed energy, the certified bound and whether it
/// holds.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EnergyBound {
    pub committed: Rat,
    pub bound: Rat,
    pub holds: bool,
}

// -------------------------------------------------------------------------------------------
// the section

/// [definition] **A refined section** (module header): the refinement's words (owned until the
/// return consumes them), the injection, the receiving map read at the cut, the anchor, each
/// station's read and the stations' faces, the end change and the balance.
#[derive(Debug)]
pub struct Section<'c> {
    field: &'c Field,
    declared: Refinement,
    words: Vec<Word<'c>>,
    injection: Vec<Vec<Rat>>,
    map: ExactRatMatrix,
    anchor: Vec<Rat>,
    reads: Vec<Vec<Rat>>,
    faces: Faces,
    end: EndChange,
    balance: RefinementBalance,
}

impl<'c> Section<'c> {
    /// **Refine a section** (module header): the operands read once at the cut (every word of the
    /// refinement reads the same medium), the change opened at rest with the request's moment
    /// injected at the source rings, `K` words of `w` full ticks with the motion continuing, the last
    /// ending at its last junction, and every station read from its anchor.
    pub fn refine(
        field: &'c Field,
        constitution: &impl ConstitutionRead,
        current: &Current,
        placements: &[&SourceMoment],
        declared: &Refinement,
        charts: &mut Charts,
    ) -> Result<Self, HnnError> {
        let operands = Operands::at_cut_charted(field, constitution, current, charts)?;
        let injection = injection(field, constitution, current, placements)?;
        Self::refine_on(field, constitution, operands, injection, declared)
    }

    /// **Refine on given operands**: the executed charts with no transient split for the pairing
    /// check ([`Pairing`]), or the cut's own.
    fn refine_on(
        field: &'c Field,
        constitution: &impl ConstitutionRead,
        operands: Operands,
        injection: Vec<Vec<Rat>>,
        declared: &Refinement,
    ) -> Result<Self, HnnError> {
        let map = constitution
            .receiving_map(declared.ring)
            .ok_or(HnnError::MissingReceivingMap {
                ring: declared.ring,
            })?
            .clone();
        let mut change = EndChange::rest(field, &operands);
        let mut words: Vec<Word<'c>> = Vec::with_capacity(declared.words);
        for n in 0..declared.words {
            let mut word = Word::continuing(
                field,
                operands.clone(),
                &change,
                &injection,
                n * declared.span,
            )?;
            word.run(declared.span)?;
            if n + 1 == declared.words {
                word.last_junction()?;
            } else {
                change = word.change()?;
            }
            words.push(word);
        }
        let last = words.last().expect("a refinement declares at least one word");
        let anchor = last
            .anchor(declared.span, declared.ring)
            .ok_or(HnnError::WordEnded {
                ticks: last.ticks(),
            })?
            .to_vec();
        let end = last.released()?.end;
        let ring = field.ring(declared.ring);
        let reads: Vec<Vec<Rat>> = (0..declared.stations)
            .map(|j| ring.rotate(&anchor, &BigInt::from(j as u64 + 1)))
            .collect();
        let logits = reads
            .iter()
            .map(|read| apply_rows(&map, read))
            .collect::<Result<Vec<_>, HnnError>>()?;
        let received: Vec<ReceivingRead> = logits
            .into_iter()
            .map(|logits| ReceivingRead::of_logits(logits, declared.grain))
            .collect();
        let faces = Faces::of_reads(&received, declared.grain)?;
        let balance = RefinementBalance::of(&words)?;
        Ok(Self {
            field,
            declared: declared.clone(),
            words,
            injection,
            map,
            anchor,
            reads,
            faces,
            end,
            balance,
        })
    }

    /// The declaration.
    pub fn declared(&self) -> &Refinement {
        &self.declared
    }

    /// The stations' faces, one per station, with their exact logits.
    pub fn faces(&self) -> &Faces {
        &self.faces
    }

    /// Each station's read `P_R^(1+j) v_R`.
    pub fn reads(&self) -> &[Vec<Rat>] {
        &self.reads
    }

    /// The receiving ring's anchor at the last junction: the section's one producing variable.
    pub fn anchor(&self) -> &[Rat] {
        &self.anchor
    }

    /// The refinement's balance.
    pub fn balance(&self) -> &RefinementBalance {
        &self.balance
    }

    /// The change the last word ended with, which the commit's deposition work reads.
    pub fn end(&self) -> &EndChange {
        &self.end
    }

    /// The largest exact bits of a wave, contact or resonator coordinate over the refinement's
    /// words, a reading.
    pub fn peak_bits(&self) -> u64 {
        self.words.iter().map(Word::peak_bits).max().unwrap_or(0)
    }

    /// Every word's carried remainders, released at its end, joined.
    pub fn released(&self) -> Result<Remainders, HnnError> {
        let mut joined = Remainders::default();
        for word in &self.words {
            joined = joined.join(&word.released()?.remainders);
        }
        Ok(joined)
    }

    /// **The release of the section** (module header): each station's top class at the grain,
    /// read over the grain fibre of its logits; width zero exactly when every station's top cell is
    /// unique, the discrete metric's one otherwise, attained at the first plural station; decided
    /// at tolerance zero by the holding rule through `receiver::release`.
    pub fn release(&self) -> Result<SectionRelease, HnnError> {
        let mut classes = Vec::with_capacity(self.faces.faces.len());
        let mut plural = Vec::new();
        for (j, face) in self.faces.faces.iter().enumerate() {
            let cells = face.cells();
            let mut top = 0;
            for (class, cell) in cells.iter().enumerate() {
                let (best, candidate) = (&cells[top], cell);
                if (&candidate.carry, candidate.phase) > (&best.carry, best.phase) {
                    top = class;
                }
            }
            let shared = cells
                .iter()
                .enumerate()
                .any(|(class, cell)| {
                    class != top
                        && cell.carry == cells[top].carry
                        && cell.phase == cells[top].phase
                });
            if shared {
                plural.push(j);
            }
            classes.push(top);
        }
        section_release(&self.declared, classes, plural)
    }

    /// **The section's Holon ratio against its targets**, one class per station, each target read
    /// at its station's phase on the response clock ([`Refinement::target_phases`]).
    pub fn compare(&self, targets: &[usize]) -> Result<HolonRatio, HnnError> {
        if targets.len() != self.declared.stations {
            return Err(HnnError::Shape {
                what: "one target per station",
                expected: self.declared.stations,
                found: targets.len(),
            });
        }
        HolonRatio::compare(self.faces.clone(), targets, &self.declared.target_phases())
    }

    /// **The section's Holon ratio at its compared stations only** (the unlocked ones; module
    /// header): each compared station's ratio as [`Section::compare`] reads it, a zero covector at
    /// the others.
    pub fn compare_partition(
        &self,
        targets: &[usize],
        compared: &[bool],
    ) -> Result<HolonRatio, HnnError> {
        if targets.len() != self.declared.stations {
            return Err(HnnError::Shape {
                what: "one target per station",
                expected: self.declared.stations,
                found: targets.len(),
            });
        }
        HolonRatio::compare_partition(
            self.faces.clone(),
            targets,
            &self.declared.target_phases(),
            compared,
        )
    }

    /// **The section's return** (module header, "Learning"): the covector at every station pulled
    /// back through `R` and the station's phase binding onto the anchor, then through the words in
    /// reverse, each by its own continuing return; the returns joined on the refinement's clock
    /// ([`join`]). It consumes the section: its words live only until here.
    pub fn pull_back(self, covector: &RatioCovector) -> Result<SectionReturn, HnnError> {
        let declared = self.declared.clone();
        let stations = covector.logits();
        if stations.len() != declared.stations {
            return Err(HnnError::Shape {
                what: "the covector's stations",
                expected: declared.stations,
                found: stations.len(),
            });
        }
        let ring = self.field.ring(declared.ring);
        let map_t = self.map.transpose()?;
        let mut anchor_covector = vec![Rat::zero(); ring.width()];
        for (j, gradient) in stations.iter().enumerate() {
            let pulled = apply_rows(&map_t, gradient)?;
            anchor_covector = add(
                &anchor_covector,
                &ring.rotate(&pulled, &-BigInt::from(j as u64 + 1)),
            );
        }
        let produced: Rat = stations
            .iter()
            .zip(&self.reads)
            .map(|(gradient, read)| -> Result<Rat, HnnError> {
                Ok(dot(gradient, &apply_rows(&self.map, read)?))
            })
            .sum::<Result<Rat, HnnError>>()?;
        let reads: Vec<(Vec<Rat>, Vec<Rat>)> = self
            .reads
            .iter()
            .cloned()
            .zip(stations.iter().cloned())
            .collect();
        let mut end: Option<ChangeCovector> = None;
        let mut returns: Vec<(WordReturn, ChangeCovector)> = Vec::with_capacity(declared.words);
        let count = self.words.len();
        for (n, word) in self.words.into_iter().enumerate().rev() {
            let mut anchors = vec![None; word.recorded().len()];
            if n + 1 == count {
                anchors[declared.span] = Some(anchor_covector.clone());
            }
            let (back, opening) =
                word.pull_back_continuing(anchors, declared.ring, end.as_ref())?;
            end = Some(opening.clone());
            returns.push((back, opening));
        }
        returns.reverse();
        let mut returned = Rat::zero();
        for (_, opening) in &returns {
            for (covector, injected) in opening.storage.iter().zip(&self.injection) {
                returned += dot(covector, injected);
            }
        }
        let joined = join(&returns, declared.span, reads)?;
        Ok(SectionReturn {
            joined,
            openings: returns.into_iter().map(|(_, opening)| opening).collect(),
            pairing: Pairing { produced, returned },
        })
    }
}

/// [definition] **A section's release** ([`Section::release`]): the decision, the width over the
/// section's fibre, each station's top class, the plural stations, the emitted classes (the
/// released section up to its first termination; empty unless released) and the first station at
/// the termination class.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SectionRelease {
    pub decision: ReleaseReturn,
    pub width: Rat,
    pub classes: Vec<usize>,
    pub plural: Vec<usize>,
    pub emitted: Vec<usize>,
    pub terminated: Option<usize>,
}

impl SectionRelease {
    /// Whether the section was released at width zero.
    pub fn released(&self) -> bool {
        matches!(self.decision, ReleaseReturn::Released { .. })
    }
}

/// **A section's release from its stations' classes and its plural stations** ([`Section::release`],
/// [`generate`]): width zero exactly when no station is plural, the discrete metric's one otherwise,
/// attained at the first plural station, decided at tolerance zero by the holding rule through
/// `receiver::release`; the released classes read up to the first termination.
fn section_release(
    declared: &Refinement,
    classes: Vec<usize>,
    plural: Vec<usize>,
) -> Result<SectionRelease, HnnError> {
    let (diameter, attaining) = match plural.first() {
        Some(&station) => (
            Rat::one(),
            WidthWitness::Coordinate {
                coordinate: station,
            },
        ),
        None => (Rat::zero(), WidthWitness::Point),
    };
    let width = ReceiverWidth::declared(
        format!("the section on receiving ring {}", declared.ring),
        "every station's top class at the grain, over the grain fibre of its logits",
        DiameterNorm::Supremum,
        diameter,
        attaining,
        classes.len().max(1),
    )?;
    let options = LawfulOptions::assemble(&width, Rat::zero(), None, false)?;
    let rule = DecisionRule::new(
        "the section's joint commit at tolerance zero",
        WithinTolerance::Release,
        BeyondTolerance::Hold,
    );
    let decision = release(&rule, &options)?;
    let terminated = classes
        .iter()
        .position(|&class| class == declared.termination);
    let emitted = match &decision {
        ReleaseReturn::Released { .. } => classes[..terminated.unwrap_or(classes.len())].to_vec(),
        _ => Vec::new(),
    };
    Ok(SectionRelease {
        decision,
        width: width.diameter().clone(),
        classes,
        plural,
        emitted,
        terminated,
    })
}

/// **The injection of several placements** at one frame: each placement's open storage
/// `P_g^(τ_g) m̃_g` ([`SourceMoment::open_storage`]) at the request's lift, summed ring by ring
/// (every placement enters through the same `E_g`, each over its own population).
pub fn injection(
    field: &Field,
    constitution: &impl ConstitutionRead,
    current: &Current,
    placements: &[&SourceMoment],
) -> Result<Vec<Vec<Rat>>, HnnError> {
    let mut storage: Vec<Vec<Rat>> = field
        .rings()
        .iter()
        .map(|ring| vec![Rat::zero(); ring.width()])
        .collect();
    for placement in placements {
        for (total, wave) in storage
            .iter_mut()
            .zip(placement.open_storage(field, constitution, current)?)
        {
            if wave.iter().any(|x| !x.is_zero()) {
                *total = add(total, &wave);
            }
        }
    }
    Ok(storage)
}

/// **A station's lock reading** at the grain `L`: its top class (the greatest grain cell, the
/// least class on a tie) and the gap in grain steps `(n_top − n_2) L + (k_top − k_2)` to the
/// runner-up cell, zero exactly when the top cell is shared (a plural reading).
fn lock_reading(face: &crate::hnn::ratio::Face, grain: u64) -> (usize, BigInt) {
    let cells = face.cells();
    let step = |cell: &crate::receiver::face::GrainCell| -> BigInt {
        &cell.carry * BigInt::from(grain) + BigInt::from(cell.phase)
    };
    let mut top = 0;
    for (class, cell) in cells.iter().enumerate() {
        if step(cell) > step(&cells[top]) {
            top = class;
        }
    }
    let runner = cells
        .iter()
        .enumerate()
        .filter(|&(class, _)| class != top)
        .map(|(_, cell)| step(cell))
        .max();
    let gap = match runner {
        Some(runner) => step(&cells[top]) - runner,
        None => BigInt::zero(),
    };
    (top, gap)
}

/// [definition; agent-inferred, U6's order repair] **The partition a training refinement compares**
/// (module header): the corruption chart of absorbing (masked) diffusion read on the stations. The
/// number `v` of locked stations is drawn uniformly from `0 … m − 1`, then `v` stations uniformly
/// (a partial Fisher–Yates draw); the rest are compared. Every partition a generation passes through
/// (nothing locked, then more) is one this law draws with positive mass, and at least one station is
/// always compared. `true` marks a locked (placed, uncompared) station.
pub fn mask(draw: &mut Draw, stations: usize) -> Vec<bool> {
    let mut order: Vec<usize> = (0..stations).collect();
    let locked = draw.below(stations.max(1));
    for i in 0..locked {
        let j = i + draw.below(stations - i);
        order.swap(i, j);
    }
    let mut visible = vec![false; stations];
    for &station in &order[..locked] {
        visible[station] = true;
    }
    visible
}

/// [definition] **The adjoint pairing of a section's return** (module header, the second check):
/// `produced = Σ_j ⟨g_j, R P_R^(1+j) v_R⟩`, the stations' covectors paired with their logits, and
/// `returned = Σ_n ⟨μ_n, injection⟩`, the returned opening covectors paired with what each word's
/// open added (the change opens at rest, so nothing else). On the executed charts with no transient split the two are equal
/// exactly; on the word's lattice they differ by the released remainders' work.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Pairing {
    pub produced: Rat,
    pub returned: Rat,
}

impl Pairing {
    /// `produced = returned`.
    pub fn holds(&self) -> bool {
        self.produced == self.returned
    }
}

/// [definition] **What a section's return yields**: the words' returns joined on the refinement's
/// clock ([`join`]), each word's covector on its opening change, and the adjoint pairing.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SectionReturn {
    pub joined: WordReturn,
    pub openings: Vec<ChangeCovector>,
    pub pairing: Pairing,
}

/// **The words' returns joined on the refinement's clock**: every element, transit and resonator
/// tick re-indexed by its word's open (`n·w`), the conductance covectors summed, the opening
/// covectors summed (each word's injection is the same moment, so its covector on `E` is their
/// sum), the stations' reads beside their covectors, and the released remainders joined.
pub fn join(
    returns: &[(WordReturn, ChangeCovector)],
    span: usize,
    reads: Vec<(Vec<Rat>, Vec<Rat>)>,
) -> Result<WordReturn, HnnError> {
    let Some((first, _)) = returns.first() else {
        return Err(HnnError::Shape {
            what: "a refinement's returns",
            expected: 1,
            found: 0,
        });
    };
    let mut joined = WordReturn {
        opening: first
            .opening
            .iter()
            .map(|wave| vec![Rat::zero(); wave.len()])
            .collect(),
        elements: vec![Vec::new(); first.elements.len()],
        transits: vec![Vec::new(); first.transits.len()],
        resonators: vec![Vec::new(); first.resonators.len()],
        conductance: vec![Rat::zero(); first.conductance.len()],
        reads,
        released: Remainders::default(),
    };
    for (n, (back, _)) in returns.iter().enumerate() {
        let offset = n * span;
        for (total, wave) in joined.opening.iter_mut().zip(&back.opening) {
            *total = add(total, wave);
        }
        for (total, ticks) in joined.elements.iter_mut().zip(&back.elements) {
            total.extend(ticks.iter().cloned().map(|mut tick| {
                tick.tick += offset;
                tick
            }));
        }
        for (total, ticks) in joined.transits.iter_mut().zip(&back.transits) {
            total.extend(ticks.iter().cloned().map(|mut tick| {
                tick.tick += offset;
                tick
            }));
        }
        for (total, ticks) in joined.resonators.iter_mut().zip(&back.resonators) {
            total.extend(ticks.iter().cloned().map(|mut tick| {
                tick.tick += offset;
                tick
            }));
        }
        for (total, term) in joined.conductance.iter_mut().zip(&back.conductance) {
            *total += term;
        }
        joined.released = joined.released.join(&back.released);
    }
    Ok(joined)
}

// -------------------------------------------------------------------------------------------
// learning

/// [definition] **The internal checks of one refinement** (module header): the balance closing,
/// the adjoint pairing (when checked), the section's release width, and the loci outside the
/// refinement's diamond (their count, and whether every one is unchanged by the deposit that
/// followed).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Checks {
    pub balance: RefinementBalance,
    pub pairing: Option<Pairing>,
    pub width: Rat,
    pub unreached: Option<(usize, bool)>,
}

/// [definition] **One refinement staged for its deposit**: the section's ratio against its
/// targets, its release, the composed return, the end change and the balance (the commit's
/// operands), and the pairing when checked.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Staged {
    pub ratio: HolonRatio,
    pub release: SectionRelease,
    pub composed: ComposedReturn,
    pub end: EndChange,
    pub balance: RefinementBalance,
    pub pairing: Option<Pairing>,
    pub released: Remainders,
    pub peak_bits: u64,
}

/// **Refine, compare and return one section** at the constitution's commit (module header,
/// "Learning"): the targets at the `locked` stations placed as the section's data ([`mask`] draws
/// the partition; none locked is the pinned September 29 path), the section refined at the cut with
/// the request's placement and the section's, released, compared at its unlocked stations only, its
/// covector pulled back through the `K` words and composed onto every locus inside the refinement's
/// diamond, both placements entering through `E_g`. With `check`, the refinement is also run on the
/// executed charts with no transient split and its return's pairing read ([`Pairing`]).
#[allow(clippy::too_many_arguments)]
pub fn stage(
    field: &Field,
    constitution: &Constitution,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    targets: &[usize],
    locked: &[bool],
    charts: &mut Charts,
    check: bool,
) -> Result<Staged, HnnError> {
    if targets.len() != declared.stations || locked.len() != declared.stations {
        return Err(HnnError::Shape {
            what: "one target and one lock per station",
            expected: declared.stations,
            found: targets.len().min(locked.len()),
        });
    }
    let cells: Vec<Option<usize>> = targets
        .iter()
        .zip(locked)
        .map(|(&target, &lock)| lock.then_some(target))
        .collect();
    // Nothing locked places nothing (the pinned September 29 path, on any receiving ring).
    let placed = if locked.iter().any(|&lock| lock) {
        Some(declared.section(field, current, &cells)?)
    } else {
        None
    };
    let placements: Vec<&SourceMoment> = std::iter::once(moment).chain(placed.as_ref()).collect();
    let compared: Vec<bool> = locked.iter().map(|lock| !lock).collect();
    let operands = Operands::at_cut_charted(field, constitution, current, charts)?;
    let injection = injection(field, constitution, current, &placements)?;
    let pairing = if check {
        let unsplit = operands.clone().unsplit()?;
        let section =
            Section::refine_on(field, constitution, unsplit, injection.clone(), declared)?;
        let covector = section.compare_partition(targets, &compared)?.covector()?;
        Some(section.pull_back(&covector)?.pairing)
    } else {
        None
    };
    let section = Section::refine_on(field, constitution, operands, injection, declared)?;
    let release = section.release()?;
    let ratio = section.compare_partition(targets, &compared)?;
    let covector = ratio.covector()?;
    let end = section.end().clone();
    let balance = section.balance().clone();
    let released = section.released()?;
    let peak_bits = section.peak_bits();
    let back = section.pull_back(&covector)?;
    let composed = compose_return(
        field,
        constitution,
        &declared.diamond(field),
        current.lift(),
        current,
        &placements,
        &back.joined,
    )?;
    Ok(Staged {
        ratio,
        release,
        composed,
        end,
        balance,
        pairing,
        released: released.join(&back.joined.released),
        peak_bits,
    })
}

/// [definition] **A generated section** ([`generate`]): its release (every station locked, at width
/// zero, or held with the stations that were plural when no unlocked station led), the refinements
/// it took, how many of their balances closed, and the stations each refinement locked, in order.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Generation {
    pub release: SectionRelease,
    pub refinements: usize,
    pub balances_closed: usize,
    pub locks: Vec<Vec<usize>>,
}

/// **Generate a section** (module header, "Relative phases between placed data"): the request's
/// placement fixed, nothing locked; each refinement reads every station jointly from the one refined
/// field with the locked data placed, and locks every unlocked station whose gap at the grain is the
/// largest (ties together). It stops when every station is locked, released at width zero (each lock
/// read a unique top cell), or when the largest gap is zero, held with the unlocked stations plural.
/// At most `m` refinements; the operands are read once at the cut.
pub fn generate(
    field: &Field,
    constitution: &impl ConstitutionRead,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    charts: &mut Charts,
) -> Result<Generation, HnnError> {
    if !field.is_source(declared.ring) {
        return Err(HnnError::MissingSourcePort {
            ring: declared.ring,
        });
    }
    let operands = Operands::at_cut_charted(field, constitution, current, charts)?;
    let stations = declared.stations;
    let mut locked: Vec<Option<usize>> = vec![None; stations];
    let mut tops: Vec<usize> = vec![declared.termination; stations];
    let mut locks: Vec<Vec<usize>> = Vec::new();
    let mut plural: Vec<usize> = Vec::new();
    let (mut refinements, mut balances_closed) = (0usize, 0usize);
    while locked.iter().any(Option::is_none) {
        let placed = declared.section(field, current, &locked)?;
        let injection = injection(field, constitution, current, &[moment, &placed])?;
        let section = Section::refine_on(field, constitution, operands.clone(), injection, declared)?;
        refinements += 1;
        balances_closed += usize::from(section.balance().closes());
        let readings: Vec<(usize, usize, BigInt)> = (0..stations)
            .filter(|&j| locked[j].is_none())
            .map(|j| {
                let (top, gap) = lock_reading(&section.faces().faces[j], declared.grain);
                (j, top, gap)
            })
            .collect();
        for &(j, top, _) in &readings {
            tops[j] = top;
        }
        let largest = readings
            .iter()
            .map(|(_, _, gap)| gap.clone())
            .max()
            .unwrap_or_else(BigInt::zero);
        if largest.is_zero() {
            plural = readings.iter().map(|&(j, ..)| j).collect();
            break;
        }
        let now: Vec<usize> = readings
            .iter()
            .filter(|(_, _, gap)| *gap == largest)
            .map(|&(j, top, _)| {
                locked[j] = Some(top);
                j
            })
            .collect();
        locks.push(now);
    }
    let classes: Vec<usize> = locked
        .iter()
        .zip(&tops)
        .map(|(lock, &top)| lock.unwrap_or(top))
        .collect();
    Ok(Generation {
        release: section_release(declared, classes, plural)?,
        refinements,
        balances_closed,
        locks,
    })
}

/// **The deposit of a set of staged refinements at one commit** (module header): every linear
/// locus's samples gathered into one window (the normal law sums its samples' terms), every factor
/// family's descent directions and feature energies summed into one step (a shared operand's
/// gradient is the sum over its uses), the loci reached united, and the refinement's reach
/// ([`Refinement::reach`]) at the most phases one of its moments occupied. No landmark and no
/// receiving-face step is staged.
pub fn deposit_of(
    constitution: &Constitution,
    declared: &Refinement,
    composed: &[ComposedReturn],
) -> Result<Deposit, HnnError> {
    let mut linear: BTreeMap<LinearLocus, Vec<crate::hnn::constitution::Sample>> = BTreeMap::new();
    let mut order: Vec<LinearLocus> = Vec::new();
    let mut factors: Vec<FactorStep> = Vec::new();
    let mut reached: Vec<Locus> = Vec::new();
    for part in composed {
        for step in &part.linear {
            if !linear.contains_key(&step.locus) {
                order.push(step.locus);
            }
            linear
                .entry(step.locus)
                .or_default()
                .extend(step.samples.iter().cloned());
        }
        for step in &part.factors {
            match factors
                .iter_mut()
                .find(|kept| same_family(&kept.gradient, &step.gradient))
            {
                Some(kept) => {
                    kept.gradient = summed(&kept.gradient, &step.gradient)?;
                    kept.energy += &step.energy;
                    // One return's covector scale over the joined windows: the largest.
                    if step.covector > kept.covector {
                        kept.covector = step.covector.clone();
                    }
                }
                None => factors.push(step.clone()),
            }
        }
        for locus in &part.reached {
            if !reached.contains(locus) {
                reached.push(*locus);
            }
        }
    }
    let linear: Vec<LinearStep> = order
        .into_iter()
        .map(|locus| LinearStep {
            locus,
            samples: linear.remove(&locus).unwrap_or_default(),
        })
        .collect();
    let phases = composed.iter().map(|part| part.phases).max().unwrap_or(0);
    Ok(Deposit::new(constitution.commit(), linear, factors, reached)
        .with_reach(declared.reach(phases)))
}

/// Whether two factor steps descend the same family.
fn same_family(left: &FactorGradient, right: &FactorGradient) -> bool {
    use FactorGradient::*;
    match (left, right) {
        (Passive { ring: a, .. }, Passive { ring: b, .. })
        | (Slices { ring: a, .. }, Slices { ring: b, .. })
        | (Standing { ring: a, .. }, Standing { ring: b, .. }) => a == b,
        (
            Resonator {
                ring: a,
                family: f,
                ..
            },
            Resonator {
                ring: b,
                family: g,
                ..
            },
        ) => a == b && f == g,
        (
            PairPort {
                ring: a,
                offset: o,
                ..
            },
            PairPort {
                ring: b,
                offset: p,
                ..
            },
        ) => a == b && o == p,
        (Storage { contact: a, .. }, Storage { contact: b, .. })
        | (Stiffness { contact: a, .. }, Stiffness { contact: b, .. })
        | (Dissipation { contact: a, .. }, Dissipation { contact: b, .. }) => a == b,
        _ => false,
    }
}

/// The sum of two descent directions of the same family.
fn summed(left: &FactorGradient, right: &FactorGradient) -> Result<FactorGradient, HnnError> {
    use FactorGradient::*;
    let rows = |a: &[Vec<Rat>], b: &[Vec<Rat>]| -> Vec<Vec<Rat>> {
        a.iter().zip(b).map(|(x, y)| add(x, y)).collect()
    };
    Ok(match (left, right) {
        (Passive { ring, gradient: a }, Passive { gradient: b, .. }) => Passive {
            ring: *ring,
            gradient: a.add(b)?,
        },
        (Slices { ring, gradient: a }, Slices { gradient: b, .. }) => Slices {
            ring: *ring,
            gradient: a
                .iter()
                .zip(b)
                .map(|((u, v), (x, y))| (add(u, x), add(v, y)))
                .collect(),
        },
        (
            Standing {
                ring,
                gradient: a,
                reach: left,
            },
            Standing {
                gradient: b,
                reach: right,
                ..
            },
        ) => {
            // The chart's rings, each with the energies of both windows (one refinement's each).
            let mut reach = left.clone();
            for (r, energy) in right {
                match reach.iter_mut().find(|(kept, _)| kept == r) {
                    Some((_, kept)) => *kept += energy,
                    None => reach.push((*r, energy.clone())),
                }
            }
            Standing {
                ring: *ring,
                gradient: add(a, b),
                reach,
            }
        }
        (
            Resonator {
                ring,
                family,
                gradient: a,
            },
            Resonator { gradient: b, .. },
        ) => Resonator {
            ring: *ring,
            family: *family,
            gradient: a + b,
        },
        (
            PairPort {
                ring,
                offset,
                outputs: a,
                current: c,
                earlier: e,
            },
            PairPort {
                outputs: b,
                current: d,
                earlier: f,
                ..
            },
        ) => PairPort {
            ring: *ring,
            offset: *offset,
            outputs: rows(a, b),
            current: rows(c, d),
            earlier: rows(e, f),
        },
        (Storage { contact, gradient: a }, Storage { gradient: b, .. }) => Storage {
            contact: *contact,
            gradient: a.add(b)?,
        },
        (Stiffness { contact, gradient: a }, Stiffness { gradient: b, .. }) => Stiffness {
            contact: *contact,
            gradient: a.add(b)?,
        },
        (Dissipation { contact, gradient: a }, Dissipation { gradient: b, .. }) => Dissipation {
            contact: *contact,
            gradient: a.add(b)?,
        },
        _ => {
            return Err(HnnError::Shape {
                what: "two descent directions of one factor family",
                expected: 1,
                found: 2,
            });
        }
    })
}

/// **Every locus's learned material as the forward pass reads it**, flattened, with its deposit
/// clock: the check of the loci a deposit did not reach.
fn material(constitution: &Constitution, field: &Field, locus: Locus) -> (Vec<Rat>, u64) {
    let mut values: Vec<Rat> = Vec::new();
    match locus {
        Locus::Element(g) => {
            values.extend(constitution.passive_factor(g).entries().iter().cloned());
            values.extend(constitution.contrast_port(g).entries().iter().cloned());
            for (u, v) in constitution.slices(g) {
                values.extend(u.iter().cloned());
                values.extend(v.iter().cloned());
            }
        }
        Locus::Standing(g) => values.extend(constitution.standing(g).iter().cloned()),
        Locus::SourcePort(g) => {
            if let Some(port) = constitution.source_port(g) {
                values.extend(port.entries().iter().cloned());
            }
            for &offset in field.offsets() {
                if let Some(pair) = constitution.pair_port(g, offset) {
                    for family in [pair.outputs(), pair.current_reads(), pair.earlier_reads()] {
                        values.extend(family.iter().flatten().cloned());
                    }
                }
            }
        }
        Locus::ReceivingMap(g) => {
            if let Some(map) = constitution.receiving_map(g) {
                values.extend(map.entries().iter().cloned());
            }
        }
        Locus::Channel(a) => {
            for form in [
                constitution.contact_storage(a),
                constitution.contact_stiffness(a),
                constitution.contact_dissipation(a),
            ] {
                values.extend(form.entries().iter().cloned());
            }
        }
        Locus::Resonator(g) => {
            if let Some(resonator) = constitution.ring_resonator(g) {
                values.extend(resonator.gains().iter().cloned());
            }
        }
        Locus::Junction(_) | Locus::Conductance(_) => {}
    }
    (values, constitution.clock(locus))
}

/// **The loci a refinement's deposit did not reach are unchanged** (module header, the third check;
/// Lean `HNN/Retention.deposit_descends`): every locus outside the refinement's diamond has the same
/// learned material and deposit clock in the successor as in the predecessor. Returns the count of
/// such loci and whether every one is unchanged.
pub fn unreached_unchanged(
    field: &Field,
    before: &Constitution,
    after: &Constitution,
    diamond: &Diamond,
) -> (usize, bool) {
    let mut count = 0;
    let mut unchanged = true;
    for locus in loci(field) {
        if diamond.retains(field, locus) && !before.released().contains(&locus) {
            continue;
        }
        count += 1;
        unchanged &= material(before, field, locus) == material(after, field, locus);
    }
    (count, unchanged)
}
